@page "/settings"
@using sv_d160cc3cb98b438295fcec09f5f754be.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => ActiveSection = "Profile"'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => ActiveSection = "Notifications"'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => ActiveSection = "Security"'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => ActiveSection = "Appearance"'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (IsLoading)
        {
            <div class="loading">Loading settings...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(ToastMessage))
        {
            <div class="toast @ToastType">
                @ToastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "Profile";
    private bool IsLoading { get; set; } = true;
    private string? ToastMessage { get; set; }
    private string ToastType { get; set; } = "success";

    // Profile state
    private string ProfileDisplayName { get; set; } = "";
    private string ProfileEmail { get; set; } = "";
    private string ProfileAvatarUrl { get; set; } = "";
    private string ProfileBio { get; set; } = "";
    private UserProfile? _savedProfile;

    // Notification state
    private bool NotifEmail { get; set; }
    private bool NotifPush { get; set; }
    private bool NotifWeeklyDigest { get; set; }
    private List<string> AllChannels { get; set; } = new();
    private HashSet<string> MutedChannels { get; set; } = new();

    // Security state
    private bool TwoFactorEnabled { get; set; }
    private DateTime? LastPasswordChange { get; set; }
    private List<ActiveSession> Sessions { get; set; } = new();
    private bool ChangePasswordExpanded { get; set; }
    private string CurrentPassword { get; set; } = "";
    private string NewPassword { get; set; } = "";
    private string ConfirmPassword { get; set; } = "";
    private string? RevokeSessionId { get; set; }

    // Appearance state
    private string SelectedTheme { get; set; } = "System";
    private string SelectedFontSize { get; set; } = "Medium";
    private string SelectedLanguage { get; set; } = "English";
    private bool CompactMode { get; set; }

    private static readonly string[] AvailableLanguages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };
    private static readonly string CurrentSessionId = "session-1";

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        IsLoading = false;
    }

    private async Task LoadAllSettings()
    {
        var profile = await SettingsService.GetProfileAsync();
        _savedProfile = profile;
        ApplyProfile(profile);

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        NotifEmail = notifs.EmailNotifications;
        NotifPush = notifs.PushNotifications;
        NotifWeeklyDigest = notifs.WeeklyDigest;
        AllChannels = new List<string>(notifs.MutedChannels.Count > 0 ? notifs.MutedChannels : new List<string> { "general", "random", "announcements" });
        MutedChannels = new HashSet<string>(notifs.MutedChannels);

        var security = await SettingsService.GetSecuritySettingsAsync();
        TwoFactorEnabled = security.TwoFactorEnabled;
        LastPasswordChange = security.LastPasswordChange;
        Sessions = new List<ActiveSession>(security.Sessions);

        var appearance = await SettingsService.GetAppearanceAsync();
        SelectedTheme = appearance.Theme;
        SelectedFontSize = appearance.FontSize;
        SelectedLanguage = appearance.Language;
        CompactMode = appearance.CompactMode;
    }

    private void ApplyProfile(UserProfile profile)
    {
        ProfileDisplayName = profile.DisplayName;
        ProfileEmail = profile.Email;
        ProfileAvatarUrl = profile.AvatarUrl;
        ProfileBio = profile.Bio;
    }

    private void ShowToast(string message, string type = "success")
    {
        ToastMessage = message;
        ToastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(4000);
        ToastMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast() => ToastMessage = null;

    // --- Profile ---
    private async Task SaveProfile()
    {
        var profile = new UserProfile(ProfileDisplayName, ProfileEmail, ProfileAvatarUrl, ProfileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
        ShowToast("Changes discarded.", "info");
    }

    // --- Notifications ---
    private void ToggleChannelMute(string channel)
    {
        if (MutedChannels.Contains(channel))
            MutedChannels.Remove(channel);
        else
            MutedChannels.Add(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(NotifEmail, NotifPush, NotifWeeklyDigest, MutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!");
    }

    // --- Security ---
    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            ShowToast("New passwords do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(CurrentPassword, NewPassword);
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
        ChangePasswordExpanded = false;
        LastPasswordChange = DateTime.UtcNow;
        ShowToast("Password updated successfully!");
    }

    private void RequestRevokeSession(string sessionId) => RevokeSessionId = sessionId;
    private void CancelRevoke() => RevokeSessionId = null;

    private async Task ConfirmRevokeSession()
    {
        if (RevokeSessionId is not null)
        {
            await SettingsService.RevokeSessionAsync(RevokeSessionId);
            Sessions = Sessions.Where(s => s.Id != RevokeSessionId).ToList();
            RevokeSessionId = null;
            ShowToast("Session revoked.");
        }
    }

    private async Task ToggleTwoFactor()
    {
        TwoFactorEnabled = !TwoFactorEnabled;
        ShowToast(TwoFactorEnabled ? "Two-factor authentication enabled." : "Two-factor authentication disabled.", "info");
        await Task.CompletedTask;
    }

    // --- Appearance ---
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!");
    }

    // --- Render methods ---
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Profile</h2>
            <div class="profile-layout">
                <div class="avatar-area">
                    <div class="avatar-preview">
                        @if (!string.IsNullOrEmpty(ProfileAvatarUrl))
                        {
                            <img src="@ProfileAvatarUrl" alt="Avatar" />
                        }
                        else
                        {
                            <div class="avatar-placeholder">No Avatar</div>
                        }
                    </div>
                    <label class="field-label">Avatar URL</label>
                    <input type="url" class="field-input" @bind="ProfileAvatarUrl" placeholder="https://..." />
                </div>
                <div class="profile-fields">
                    <div class="field-group">
                        <label class="field-label">Display Name</label>
                        <input type="text" class="field-input" @bind="ProfileDisplayName" />
                    </div>
                    <div class="field-group">
                        <label class="field-label">Email</label>
                        <input type="email" class="field-input" @bind="ProfileEmail" />
                    </div>
                    <div class="field-group">
                        <label class="field-label">Bio</label>
                        <textarea class="field-input field-textarea" @bind="ProfileBio" rows="4"></textarea>
                    </div>
                </div>
            </div>
            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Notifications</h2>
            <div class="toggle-group">
                <div class="toggle-row">
                    <span>Email Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="NotifEmail" />
                        <span class="slider"></span>
                    </label>
                </div>
                <div class="toggle-row">
                    <span>Push Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="NotifPush" />
                        <span class="slider"></span>
                    </label>
                </div>
                <div class="toggle-row">
                    <span>Weekly Digest</span>
                    <label class="switch">
                        <input type="checkbox" @bind="NotifWeeklyDigest" />
                        <span class="slider"></span>
                    </label>
                </div>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in AllChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox" checked="@MutedChannels.Contains(channel)" @onchange="() => ToggleChannelMute(channel)" />
                        <span>#@channel</span>
                    </label>
                }
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <section class="settings-section">
            <h2>Security</h2>

            <!-- Change Password Panel -->
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => ChangePasswordExpanded = !ChangePasswordExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(ChangePasswordExpanded ? "▾" : "▸")</span>
                </button>
                @if (ChangePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="field-group">
                            <label class="field-label">Current Password</label>
                            <input type="password" class="field-input" @bind="CurrentPassword" />
                        </div>
                        <div class="field-group">
                            <label class="field-label">New Password</label>
                            <input type="password" class="field-input" @bind="NewPassword" />
                        </div>
                        <div class="field-group">
                            <label class="field-label">Confirm New Password</label>
                            <input type="password" class="field-input" @bind="ConfirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                        @if (LastPasswordChange.HasValue)
                        {
                            <p class="hint-text">Last changed: @LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                        }
                    </div>
                }
            </div>

            <!-- Two-Factor Auth -->
            <div class="toggle-row tfa-row">
                <div>
                    <span>Two-Factor Authentication</span>
                    <span class="status-badge @(TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                        @(TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <label class="switch">
                    <input type="checkbox" checked="@TwoFactorEnabled" @onchange="async () => await ToggleTwoFactor()" />
                    <span class="slider"></span>
                </label>
            </div>

            <!-- Active Sessions -->
            <h3>Active Sessions</h3>
            <div class="sessions-table-wrapper">
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (session.Id != CurrentSessionId)
                                    {
                                        <button class="btn btn-danger btn-sm" @onclick="() => RequestRevokeSession(session.Id)">Revoke</button>
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>

            <!-- Revoke Confirmation Dialog -->
            @if (RevokeSessionId is not null)
            {
                <div class="dialog-overlay">
                    <div class="dialog">
                        <h4>Revoke Session</h4>
                        <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
                        <div class="dialog-actions">
                            <button class="btn btn-danger" @onclick="ConfirmRevokeSession">Yes, Revoke</button>
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Appearance</h2>

            <div class="field-group">
                <label class="field-label">Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@theme" checked="@(SelectedTheme == theme)" @onchange="() => SelectedTheme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <div class="field-group">
                <label class="field-label">Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@size" checked="@(SelectedFontSize == size)" @onchange="() => SelectedFontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <div class="field-group">
                <label class="field-label">Language</label>
                <select class="field-input" @bind="SelectedLanguage">
                    @foreach (var lang in AvailableLanguages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="toggle-row">
                <span>Compact Mode</span>
                <label class="switch">
                    <input type="checkbox" @bind="CompactMode" />
                    <span class="slider"></span>
                </label>
            </div>

            <!-- Live Preview -->
            <div class="preview-area @GetPreviewClasses()">
                <h4>Live Preview</h4>
                <p class="preview-text">This is how your content will look with the selected settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>Theme: @SelectedTheme | Font: @SelectedFontSize | Compact: @(CompactMode ? "Yes" : "No")</p>
                </div>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{SelectedTheme.ToLowerInvariant()}");
        classes.Add($"preview-font-{SelectedFontSize.ToLowerInvariant()}");
        if (CompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

