toolArgs.file_text:
.settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
    background: #f8f9fa;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: #ffffff;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    color: #555;
    font-weight: 500;
    transition: all 0.15s ease;
    border-left: 3px solid transparent;
}

.settings-sidebar li:hover {
    background: #f0f4ff;
    color: #1a73e8;
}

.settings-sidebar li.active {
    background: #e8f0fe;
    color: #1a73e8;
    border-left-color: #1a73e8;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Content */
.settings-content {
    flex: 1;
    padding: 2rem 3rem;
    max-width: 800px;
    position: relative;
}

.settings-section h2 {
    margin: 0 0 1.5rem;
    font-size: 1.5rem;
    color: #202124;
}

.settings-section h3 {
    margin: 1.5rem 0 0.75rem;
    font-size: 1.1rem;
    color: #333;
}

.loading {
    padding: 2rem;
    color: #666;
    font-size: 1.1rem;
}

/* Fields */
.field-group {
    margin-bottom: 1.25rem;
}

.field-label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    font-size: 0.9rem;
    color: #444;
}

.field-input {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.15s;
    box-sizing: border-box;
}

.field-input:focus {
    outline: none;
    border-color: #1a73e8;
    box-shadow: 0 0 0 2px rgba(26, 115, 232, 0.1);
}

.field-textarea {
    resize: vertical;
    font-family: inherit;
}

/* Profile Layout */
.profile-layout {
    display: flex;
    gap: 2rem;
    margin-bottom: 1.5rem;
}

.avatar-area {
    flex-shrink: 0;
    width: 180px;
}

.avatar-preview {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    overflow: hidden;
    margin-bottom: 0.75rem;
    background: #e0e0e0;
